preConditionHook:
// SPRING (long): the bar's low trades BELOW the one-bar-shifted window low by
// at least minPenetrationAtr ATRs and the bar CLOSES BACK at or above that
// level; the short side is the upthrust at range resistance. The FLOOR is what
// distinguishes this from SmallBreakoutTrapReversal, which CAPS the same
// penetration -- opposite bounds on the same event, so neither is the other at
// any parameter (merge decision 11).
//
// THE LEVEL, merge decision 7: bars 1..rangeLookback. EL's Extremes() -- which
// Highest()/Lowest() call -- seeds at the FIRST bar of the window and scans the
// rest with a strict, tolerance-carrying comparison, so the loop seeds at bar 1
// and runs 2..rangeLookback. SmallBreakoutTrapReversal is the reference.
//
// WFSafe_AvgTrueRange is MultiWalk's ROLLING accumulator, not a fresh N-term
// mean: seeded with a full sum on the study's first calculated bar and
// thereafter S += TrueRange; S -= TrueRange[Length]; as TWO statements, because
// EasyLanguage evaluates S[1] + in - out left to right and folding it rounds
// differently. It re-seeds when the length changes. AtrProfitTarget carries the
// measurement notes.
//
// The margin is an ATR fraction, never ticks (merge decision 7). Every term is
// a price DIFFERENCE, so the rule passes the shift test.
//
// Deepest bar touched: max(rangeLookback, atrLength + 1).
priorLow = low[1];
priorHigh = high[1];
for (int i = 2; i <= (int)rangeLookback; ++i) {
    if (el_lt(low[i], priorLow)) priorLow = low[i];
    if (el_gt(high[i], priorHigh)) priorHigh = high[i];
}
if (atrLen != (int)atrLength) {
    atrSum = 0.0;
    for (int i = 0; i < (int)atrLength; ++i) {
        double hi = high[i] > close[i + 1] ? high[i] : close[i + 1];
        double lo = low[i] < close[i + 1] ? low[i] : close[i + 1];
        atrSum += hi - lo;
    }
    atrLen = (int)atrLength;
} else {
    const int out = (int)atrLength;
    double hiIn = high[0] > close[1] ? high[0] : close[1];
    double loIn = low[0] < close[1] ? low[0] : close[1];
    double hiOut = high[out] > close[out + 1] ? high[out] : close[out + 1];
    double loOut = low[out] < close[out + 1] ? low[out] : close[out + 1];
    atrSum += hiIn - loIn;
    atrSum -= hiOut - loOut;
}
atr = atrSum / (int)atrLength;
penetration = minPenetrationAtr * atr;
